package main

import (
	e2ap "ridenext.co.in/goasn1/e2sm"
	"encoding/hex"
	"encoding/json"
	"fmt"
)

func main() {
   msg, _ := hex.DecodeString("")
   //msg, _ := hex.DecodeString("")

   st := e2ap.Stream{}
   fmt.Println(msg)
   st.Init(msg)
   pdu := e2ap.E2SMPDU{}
   pdu.Unpack(&st)
   jsonData, _ := json.Marshal(pdu)
   fmt.Printf("PDU = %s\n", jsonData)
}
